// Auto-generated retina-crisp embedded partner logos + CMS partner normalizer
export const PARTNER_CATALOG_VERSION = "2026-11-05-v3";

export const EMBEDDED_PARTNER_LOGOS: Record<string, string> = {
  "gob": "data:image/webp;base64,",
  "pksf": "data:image/webp;base64,",
  "mra": "data:image/webp;base64,",
  "unicef": "data:image/webp;base64,",
  "wateraid": "data:image/webp;base64,",
  "savethechildren": "data:image/webp;base64,",
  "usaid": "data:image/webp;base64,",
  "care": "data:image/webp;base64,",
  "worldbank": "data:image/webp;base64,",
  "winrock": "data:image/webp;base64,",
  "swisscontact": "data:image/webp;base64,"
};

export interface PartnerLike {
  id?: string;
  name?: string;
  shortName?: string;
  category?: string;
  logoUrl?: string;
  websiteUrl?: string;
}

export const DEFAULT_PARTNER_ITEMS = [
  { id: "p-1", name: "Government of Bangladesh (GoB)", category: "Government", logoUrl: "/assets/gob_logo.png", websiteUrl: "https://bangladesh.gov.bd" },
  { id: "p-2", name: "PKSF (Palli Karma-Sahayak Foundation)", category: "Government", logoUrl: "/assets/pksf_logo.png", websiteUrl: "https://pksf.org.bd" },
  { id: "p-3", name: "Microcredit Regulatory Authority (MRA)", category: "Government", logoUrl: "/assets/mra_logo.png", websiteUrl: "https://mra.gov.bd" },
  { id: "p-4", name: "UNICEF Bangladesh", category: "UN Agencies", logoUrl: "/assets/unicef_logo.png", websiteUrl: "https://unicef.org/bangladesh" },
  { id: "p-5", name: "WaterAid / Water.org", category: "International NGO", logoUrl: "/assets/wateraid_logo.png", websiteUrl: "https://wateraid.org" },
  { id: "p-6", name: "Save the Children", category: "International NGO", logoUrl: "/assets/savethechildren_logo.png", websiteUrl: "https://savethechildren.net" },
  { id: "p-7", name: "USAID", category: "International NGO", logoUrl: "/assets/usaid_logo.png", websiteUrl: "https://usaid.gov" },
  { id: "p-8", name: "CARE Bangladesh", category: "International NGO", logoUrl: "/assets/care_logo.png", websiteUrl: "https://carebangladesh.org" },
];

export function matchLogoKeyFromUrl(rawUrl?: string | null): string | null {
  if (!rawUrl) return null;
  const url = rawUrl.toLowerCase();
  if (url.includes("gob_logo")) return "gob";
  if (url.includes("pksf_logo")) return "pksf";
  if (url.includes("mra_logo")) return "mra";
  if (url.includes("unicef_logo")) return "unicef";
  if (url.includes("wateraid_logo")) return "wateraid";
  if (url.includes("savethechildren_logo") || url.includes("sci_logo")) return "savethechildren";
  if (url.includes("usaid_logo")) return "usaid";
  if (url.includes("care_logo")) return "care";
  if (url.includes("worldbank_logo")) return "worldbank";
  if (url.includes("winrock_logo")) return "winrock";
  if (url.includes("swisscontact_logo")) return "swisscontact";
  return null;
}

export function matchKnownPartnerKey(partner?: PartnerLike | null): string | null {
  if (!partner) return null;
  const fromUrl = matchLogoKeyFromUrl(partner.logoUrl);
  if (fromUrl) return fromUrl;

  const id = (partner.id || "").toLowerCase();
  const name = (partner.name || "").toLowerCase();

  if (id === "p-1" || name.includes("government of bangladesh") || name.includes("(gob)")) return "gob";
  if (id === "p-2" || name.includes("pksf") || name.includes("palli karma")) return "pksf";
  if (id === "p-3" || name.includes("microcredit regulatory") || name.includes("(mra)")) return "mra";
  if (id === "p-4" || name.includes("unicef")) return "unicef";
  if (id === "p-5" || name.includes("water.org") || name.includes("wateraid")) return "wateraid";
  if (id === "p-6" || name.includes("save the children")) return "savethechildren";
  if (id === "p-7" || name.includes("usaid")) return "usaid";
  if (id === "p-8" || name.includes("care")) return "care";
  if (id === "p-9" || name.includes("world bank")) return "worldbank";
  if (id === "p-10" || name.includes("winrock")) return "winrock";
  if (id === "p-11" || name.includes("swisscontact")) return "swisscontact";
  return null;
}

export function getShortPartnerLabel(partner?: PartnerLike | null): string {
  if (!partner?.name) return "Partner";
  const key = matchKnownPartnerKey(partner);
  switch (key) {
    case "gob": return "Gov. of Bangladesh";
    case "pksf": return "PKSF Foundation";
    case "mra": return "MRA Authority";
    case "unicef": return "UNICEF";
    case "wateraid": return "WaterAid / Water.org";
    case "savethechildren": return "Save the Children";
    case "usaid": return "USAID";
    case "care": return "CARE Bangladesh";
    case "worldbank": return "The World Bank";
    case "winrock": return "Winrock Int'l";
    case "swisscontact": return "Swisscontact";
    default:
      return partner.name.replace(/\s*\([^)]*\)/g, "").trim();
  }
}

export function resolvePartnerLogo(partner?: PartnerLike | null): string {
  if (!partner) return "";
  const rawUrl = (partner.logoUrl || "").trim();

  // 1. If the logoUrl points to one of our 11 official partner logos, serve the embedded high-DPI WebP data URI
  const urlKey = matchLogoKeyFromUrl(rawUrl);
  if (urlKey && EMBEDDED_PARTNER_LOGOS[urlKey]) {
    return EMBEDDED_PARTNER_LOGOS[urlKey];
  }

  // 2. If admin uploaded a custom image or selected a non-partner library asset, respect it
  const isLegacyBrokenUrl =
    !rawUrl ||
    rawUrl.includes("wikimedia.org") ||
    rawUrl.includes("clearbit.com") ||
    rawUrl.includes("wikipedia.org");

  if (!isLegacyBrokenUrl) {
    return rawUrl;
  }

  // 3. Otherwise match by partner ID or name to the embedded high-DPI WebP data URI
  const nameKey = matchKnownPartnerKey(partner);
  if (nameKey && EMBEDDED_PARTNER_LOGOS[nameKey]) {
    return EMBEDDED_PARTNER_LOGOS[nameKey];
  }

  return getPartnerFallbackSvg(partner.name || "Partner");
}

export function getPartnerFallbackSvg(name = "Partner"): string {
  const cleanName = name.replace(/\([^)]*\)/g, "").trim() || "Partner";
  const initials = cleanName
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() || "")
    .join("") || "VP";

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="180" height="80" viewBox="0 0 180 80">
    <defs>
      <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="#004B8D"/>
        <stop offset="100%" stop-color="#0284c7"/>
      </linearGradient>
    </defs>
    <rect x="4" y="4" width="172" height="72" rx="18" fill="#f0f9ff" stroke="#bae6fd" stroke-width="2"/>
    <circle cx="42" cy="40" r="22" fill="url(#g)"/>
    <text x="42" y="46" text-anchor="middle" font-family="-apple-system, BlinkMacSystemFont, sans-serif" font-size="16" font-weight="800" fill="#ffffff">${initials}</text>
    <text x="108" y="45" text-anchor="middle" font-family="-apple-system, BlinkMacSystemFont, sans-serif" font-size="13" font-weight="700" fill="#0f172a">${cleanName.slice(0, 12)}</text>
  </svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

export function ensurePartners(data: Record<string, any>): Record<string, any> {
  if (!data || typeof data !== "object") return data;
  const existing = Array.isArray(data.partners) ? data.partners : [];
  if (existing.length === 0) {
    return {
      ...data,
      partners: DEFAULT_PARTNER_ITEMS,
      partnerCatalogVersion: PARTNER_CATALOG_VERSION,
    };
  }

  const defaultByKey = new Map<string, (typeof DEFAULT_PARTNER_ITEMS)[number]>();
  for (const item of DEFAULT_PARTNER_ITEMS) {
    const k = matchKnownPartnerKey(item);
    if (k) defaultByKey.set(k, item);
  }

  const repaired = existing.map((item: any) => {
    if (!item || typeof item !== "object") return item;
    const key = matchKnownPartnerKey(item);
    const def = key ? defaultByKey.get(key) : undefined;
    const rawLogo = typeof item.logoUrl === "string" ? item.logoUrl.trim() : "";
    const isBrokenExternal =
      !rawLogo ||
      rawLogo.includes("wikimedia.org") ||
      rawLogo.includes("clearbit.com") ||
      rawLogo.includes("wikipedia.org");

    if (def && isBrokenExternal) {
      return {
        ...item,
        logoUrl: def.logoUrl,
      };
    }
    return item;
  });

  return {
    ...data,
    partners: repaired,
    partnerCatalogVersion: PARTNER_CATALOG_VERSION,
  };
}
